export function AdminSocialMediaPage() {
  const [settingId, setSettingId] = useState('')
  const [links, setLinks] = useState(defaultLinks)
  const [message, setMessage] = useState('')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)

  const loadLinks = () => {
    setLoading(true)
    setMessage('')
    api
      .list('settings', '?search=socialMediaLinks&limit=10')
      .then((payload) => {
        const setting = (payload.data || []).find((item) => item.key === 'socialMediaLinks')
        const savedLinks = Array.isArray(setting?.value?.links) ? setting.value.links : []
        setSettingId(setting?._id || '')
        setLinks(savedLinks.length ? savedLinks : defaultLinks)
      })
      .catch((error) => setMessage(error.message || 'Social media links could not be loaded.'))
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    loadLinks()
  }, [])

  const updateLink = (index, key, value) => {
    setLinks((current) => current.map((item, itemIndex) => (itemIndex === index ? { ...item, [key]: value } : item)))
  }

  const addLink = () => {
    setLinks((current) => [...current, { platform: 'Website', label: 'Social Link', url: '', enabled: true }])
  }

  const removeLink = (index) => {
    setLinks((current) => current.filter((_, itemIndex) => itemIndex !== index))
  }

  const save = async () => {
    setSaving(true)
    setMessage('')

    const cleanLinks = links.map((item) => ({
      platform: String(item.platform || '').trim() || 'Website',
      label: String(item.label || '').trim() || String(item.platform || 'Social').trim(),
      url: String(item.url || '').trim(),
      enabled: item.enabled !== false,
    }))

    const invalidLink = cleanLinks.find((item) => item.url && !/^https?:\/\//i.test(item.url))
    if (invalidLink) {
      setSaving(false)
      setMessage(`${invalidLink.label} URL must start with http:// or https://`)
      return
    }

    const payload = {
      key: 'socialMediaLinks',
      group: 'website',
      value: { links: cleanLinks },
    }

    try {
      if (settingId) {
        await api.update('settings', settingId, payload)
      } else {
        const created = await api.create('settings', payload)
        setSettingId(created.data?._id || '')
      }
      window.dispatchEvent(new Event('social-media-links-updated'))
      setMessage('Social media links saved successfully.')
    } catch (error) {
      setMessage(error.message || 'Social media links could not be saved.')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="grid gap-5">
      <Toolbar actionLabel="Add Link" onAction={addLink} subtitle="Manage footer social media links shown on users and recruiter frontends." title="Social Media" />
      {message && <p className="rounded-[7px] bg-blue-50 p-4 text-sm font-bold text-blue-700">{message}</p>}
      <AdminCard>
        {loading ? (
          <div className="h-56 animate-pulse rounded-[7px] bg-slate-100" />
        ) : (
          <div className="grid gap-4">
            {links.map((item, index) => (
              <div className="grid gap-3 rounded-[7px] border border-slate-200 bg-slate-50 p-4 lg:grid-cols-[0.7fr_0.8fr_1.4fr_auto_auto] lg:items-end" key={`${item.platform}-${index}`}>
                <LabeledInput label="Platform" onChange={(value) => updateLink(index, 'platform', value)} placeholder="Facebook" value={item.platform} />
                <LabeledInput label="Label" onChange={(value) => updateLink(index, 'label', value)} placeholder="Follow us" value={item.label} />
                <LabeledInput label="URL" onChange={(value) => updateLink(index, 'url', value)} placeholder="https://facebook.com/yourpage" value={item.url} />
                <label className="flex min-h-11 items-center gap-3 rounded-[7px] bg-white px-4 text-sm font-black text-slate-600">
                  <input checked={item.enabled !== false} onChange={(event) => updateLink(index, 'enabled', event.target.checked)} type="checkbox" />
                  <StatusBadge status={item.enabled !== false ? 'Active' : 'Inactive'} />
                </label>
                <button className="inline-flex min-h-11 items-center justify-center gap-2 rounded-[7px] bg-rose-50 px-4 text-sm font-black text-rose-700" onClick={() => removeLink(index)} type="button">
                  <Trash2 size={16} /> Remove
                </button>
              </div>
            ))}
            <div className="flex flex-col gap-2 sm:flex-row sm:justify-end">
              <button className="inline-flex items-center justify-center gap-2 rounded-[7px] bg-slate-100 px-5 py-2.5 text-sm font-black text-slate-700" onClick={addLink} type="button">
                <Plus size={16} /> Add Another
              </button>
              <button className="rounded-[7px] bg-blue-600 px-5 py-2.5 text-sm font-black text-white shadow-lg shadow-blue-100 disabled:opacity-60" disabled={saving} onClick={save} type="button">
                {saving ? 'Saving...' : 'Save Social Media'}
              </button>
            </div>
          </div>
        )}
      </AdminCard>
    </div>
  )
}

function LabeledInput({ label, onChange, placeholder, value }) {
  return (
    <label className="grid gap-1">
      <span className="text-xs font-black uppercase tracking-wide text-slate-400">{label}</span>
      <input className="input" onChange={(event) => onChange(event.target.value)} placeholder={placeholder} type="text" value={value || ''} />
    </label>
  )
}

import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { BriefcaseBusiness, Building2, Eye, EyeOff, Lock, Mail, Phone, UserRound, X } from 'lucide-react'
import { getDashboardPath, getRecruiterVerificationPath, getRecruiterVerificationStatus, normalizeRole, storeAuthSession } from '../routes/authRouting'
import { api } from '../services/api'

const candidateInitial = {
  name: '',
  phone: '',
  email: '',
  password: '',
}

const recruiterInitial = {
  companyName: '',
  businessEmail: '',
  phone: '',
  industry: '',
  password: '',
  confirmPassword: '',
  termsAccepted: false,
}

export function AuthModal({ initialMode = 'login', onClose, onSuccess, open }) {
  const navigate = useNavigate()
  const [mode, setMode] = useState(initialMode)
  const [candidateForm, setCandidateForm] = useState(candidateInitial)
  const [recruiterForm, setRecruiterForm] = useState(recruiterInitial)
  const [message, setMessage] = useState('')
  const [loading, setLoading] = useState(false)
  const isRecruiter = mode.startsWith('recruiter')
  const isRegister = mode.endsWith('register')

  useEffect(() => {
    if (!open) return
    setMode(initialMode)
    setMessage('')
  }, [initialMode, open])

  if (!open) return null

  const updateCandidate = (key, value) => setCandidateForm((current) => ({ ...current, [key]: value }))
  const updateRecruiter = (key, value) => {
    const nextValue = key === 'phone' ? value.replace(/\D/g, '').slice(0, 10) : value
    setRecruiterForm((current) => ({ ...current, [key]: nextValue }))
  }

  const finishAuth = (payload, fallbackPath) => {
    storeAuthSession(payload)
    onSuccess?.()
    onClose?.()
    navigate(fallbackPath || getDashboardPath(payload.data.role))
  }

  const submitCandidate = async (event) => {
    event.preventDefault()
    setLoading(true)
    setMessage('')

    try {
      const payload = isRegister
        ? await api.register({ ...candidateForm, role: 'Candidate' })
        : await api.login({ email: candidateForm.email, password: candidateForm.password })
      finishAuth(payload)
    } catch (error) {
      setMessage(error.message || 'Authentication failed. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  const submitRecruiter = async (event) => {
    event.preventDefault()
    setLoading(true)
    setMessage('')

    try {
      if (isRegister) {
        if (!recruiterForm.termsAccepted) throw new Error('Please accept recruiter terms and hiring policies.')
        if (recruiterForm.password !== recruiterForm.confirmPassword) throw new Error('Password and confirm password do not match.')

        const payload = await api.register({
          name: recruiterForm.companyName,
          email: recruiterForm.businessEmail,
          phone: recruiterForm.phone,
          password: recruiterForm.password,
          role: 'recruiter',
        })

        await api.employerRegister({
          companyName: recruiterForm.companyName,
          businessEmail: recruiterForm.businessEmail,
          phone: recruiterForm.phone,
          industry: recruiterForm.industry,
        })

        finishAuth(payload, '/recruiter-documents')
        return
      }

      const payload = await api.employerLogin({ email: recruiterForm.businessEmail, password: recruiterForm.password })
      if (normalizeRole(payload.data.role) !== 'recruiter') {
        throw new Error('Only recruiter accounts can login from this option.')
      }
      storeAuthSession(payload, { role: 'recruiter' })
      const status = getRecruiterVerificationStatus()
      onSuccess?.()
      onClose?.()
      navigate(status === 'approved' ? getDashboardPath(payload.data.role) : getRecruiterVerificationPath(status))
    } catch (error) {
      setMessage(error.message || 'Recruiter authentication failed. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  const switchMode = (nextMode) => {
    setMode(nextMode)
    setMessage('')
  }

  return (
    <div className="fixed inset-0 z-[120] grid place-items-center bg-slate-950/55 px-4 py-5 backdrop-blur-sm">
      <div className="relative max-h-[calc(100dvh-2.5rem)] w-full max-w-[920px] overflow-y-auto rounded-[8px] bg-white shadow-2xl shadow-slate-950/30">
        <button
          aria-label="Close auth modal"
          className="absolute right-4 top-4 z-10 grid h-10 w-10 place-items-center rounded-full bg-white/90 text-slate-500 shadow-sm ring-1 ring-slate-200 transition hover:text-[#ff8a00]"
          onClick={onClose}
          type="button"
        >
          <X size={20} />
        </button>

        <div className="grid lg:grid-cols-[0.9fr_1.1fr]">
          <div className="hidden bg-gradient-to-br from-[#0057B8] via-[#0d72c8] to-[#ff8a00] p-8 text-white lg:block">
            <div className="grid h-13 w-13 place-items-center rounded-[7px] bg-white/15">
              {isRecruiter ? <Building2 size={26} /> : <BriefcaseBusiness size={26} />}
            </div>
            <p className="mt-6 text-sm font-black uppercase tracking-[0.18em] text-white/80">
              {isRecruiter ? 'Recruiter Workspace' : 'Candidate Access'}
            </p>
            <h2 className="mt-3 text-4xl font-black leading-tight">
              {isRecruiter ? 'Hire and manage talent faster.' : 'Find verified jobs faster.'}
            </h2>
            <div className="mt-8 grid gap-3 text-sm font-semibold">
              {[
                isRecruiter ? 'Post jobs and review applications' : 'Apply to verified openings',
                isRecruiter ? 'Track recruiter verification' : 'Track applications and saved jobs',
                isRecruiter ? 'Manage company hiring dashboard' : 'Build your candidate profile',
              ].map((item) => (
                <p className="rounded-[7px] bg-white/15 px-4 py-3 ring-1 ring-white/15" key={item}>{item}</p>
              ))}
            </div>
          </div>

          <div className="max-h-[88vh] overflow-y-auto p-5 sm:p-7">
            <div className="pr-12">
              <h2 className="text-2xl font-black text-slate-950">
                {isRecruiter ? (isRegister ? 'Recruiter Register' : 'Recruiter Login') : isRegister ? 'Register' : 'Login'}
              </h2>
              <p className="mt-1 text-sm font-semibold text-slate-500">
                {isRecruiter ? 'Access recruiter hiring tools.' : 'Access your INSEET account.'}
              </p>
            </div>

            <div className="mt-5 grid grid-cols-2 gap-2 rounded-[7px] bg-slate-100 p-1 text-sm font-black">
              <button
                className={!isRegister ? activeTabClass : idleTabClass}
                onClick={() => switchMode(isRecruiter ? 'recruiter-login' : 'login')}
                type="button"
              >
                Login
              </button>
              <button
                className={isRegister ? activeTabClass : idleTabClass}
                onClick={() => switchMode(isRecruiter ? 'recruiter-register' : 'register')}
                type="button"
              >
                Register
              </button>
            </div>
            <div className="mt-3 flex flex-wrap items-center gap-2 text-sm font-semibold text-slate-500">
              <span>{isRegister ? 'Already have an account?' : 'New here?'}</span>
              <button
                className="font-black text-[#0057B8] underline-offset-4 hover:text-[#ff8a00] hover:underline"
                onClick={() => switchMode(isRecruiter ? (isRegister ? 'recruiter-login' : 'recruiter-register') : (isRegister ? 'login' : 'register'))}
                type="button"
              >
                {isRegister ? 'Login' : 'Register'}
              </button>
            </div>

            {isRecruiter ? (
              <form className="mt-5 grid gap-4" onSubmit={submitRecruiter}>
                {isRegister && (
                  <>
                    <ModalField icon={Building2} label="Company Name" onChange={(e) => updateRecruiter('companyName', e.target.value)} placeholder="Company name" required value={recruiterForm.companyName} />
                    <ModalField icon={Phone} label="Phone Number" onChange={(e) => updateRecruiter('phone', e.target.value)} placeholder="10 digit mobile number" required value={recruiterForm.phone} />
                    <ModalField icon={BriefcaseBusiness} label="Industry" onChange={(e) => updateRecruiter('industry', e.target.value)} placeholder="IT, HR, Recruitment..." value={recruiterForm.industry} />
                  </>
                )}
                <ModalField icon={Mail} label="Business Email" onChange={(e) => updateRecruiter('businessEmail', e.target.value)} placeholder="hr@company.com" required type="email" value={recruiterForm.businessEmail} />
                <ModalField icon={Lock} label="Password" onChange={(e) => updateRecruiter('password', e.target.value)} placeholder="Password" required type="password" value={recruiterForm.password} />
                {isRegister && (
                  <>
                    <ModalField icon={Lock} label="Confirm Password" onChange={(e) => updateRecruiter('confirmPassword', e.target.value)} placeholder="Confirm password" required type="password" value={recruiterForm.confirmPassword} />
                    <label className="flex items-start gap-3 rounded-[7px] bg-orange-50 p-3 text-sm font-semibold text-slate-600">
                      <input checked={recruiterForm.termsAccepted} className="mt-1" onChange={(e) => updateRecruiter('termsAccepted', e.target.checked)} type="checkbox" />
                      I agree to recruiter terms and hiring policies.
                    </label>
                  </>
                )}
                {message && <p className="rounded-[7px] bg-orange-50 p-3 text-sm font-bold text-[#bd5f00]">{message}</p>}
                <button className={submitClass} disabled={loading} type="submit">
                  {loading ? 'Please wait...' : isRegister ? 'Register Recruiter' : 'Recruiter Login'}
                </button>
              </form>
            ) : (
              <form className="mt-5 grid gap-4" onSubmit={submitCandidate}>
                {isRegister && (
                  <>
                    <ModalField icon={UserRound} label="Full Name" onChange={(e) => updateCandidate('name', e.target.value)} placeholder="Your full name" required value={candidateForm.name} />
                    <ModalField icon={Phone} label="Phone Number" onChange={(e) => updateCandidate('phone', e.target.value)} placeholder="Phone number" value={candidateForm.phone} />
                  </>
                )}
                <ModalField icon={Mail} label="Email" onChange={(e) => updateCandidate('email', e.target.value)} placeholder="you@example.com" required type="email" value={candidateForm.email} />
                <ModalField icon={Lock} label="Password" onChange={(e) => updateCandidate('password', e.target.value)} placeholder="Password" required type="password" value={candidateForm.password} />
                {message && <p className="rounded-[7px] bg-orange-50 p-3 text-sm font-bold text-[#bd5f00]">{message}</p>}
                <button className={submitClass} disabled={loading} type="submit">
                  {loading ? 'Please wait...' : isRegister ? 'Register' : 'Login'}
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

const activeTabClass = 'rounded-[6px] bg-white px-3 py-2 text-[#ff8a00] shadow-sm'
const idleTabClass = 'rounded-[6px] px-3 py-2 text-slate-500 transition hover:text-slate-900'
const submitClass = 'inline-flex min-h-11 items-center justify-center rounded-[7px] bg-[#ff8a00] px-5 py-2.5 text-sm font-black text-white shadow-lg shadow-[#ff8a00]/20 transition hover:-translate-y-0.5 hover:bg-[#e87500] disabled:cursor-not-allowed disabled:opacity-60'

function ModalField({ icon: Icon, label, type = 'text', ...props }) {
  const [showPassword, setShowPassword] = useState(false)
  const isPassword = type === 'password'

  return (
    <label>
      <span className="text-sm font-bold text-slate-700">{label}</span>
      <div className="mt-2 flex items-center gap-3 rounded-[7px] border border-slate-200 px-4 py-3 focus-within:border-[#ff8a00] focus-within:ring-4 focus-within:ring-orange-100">
        <Icon className="text-[#ff8a00]" size={18} />
        <input className="w-full bg-transparent text-sm font-semibold outline-none placeholder:text-slate-400" {...props} type={isPassword && showPassword ? 'text' : type} />
        {isPassword && <button aria-label={showPassword ? 'Hide password' : 'Show password'} className="text-slate-400 transition hover:text-[#ff8a00]" onClick={() => setShowPassword((value) => !value)} type="button">{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button>}
      </div>
    </label>
  )
}

import { useEffect, useState } from 'react'
import { Link, NavLink, Outlet, useLocation, useNavigate } from 'react-router-dom'
import { ArrowRight, Bell, BriefcaseBusiness, Building2, CalendarDays, ChevronDown, ChevronRight, ClipboardList, CreditCard, Download, Lock, LogOut, Mail, MapPin, Menu, MessageCircle, Phone, Search, Send, Share2, ShieldCheck, Sparkles, Star, UserRound, Users, Wallet, X } from 'lucide-react'
import { AuthModal } from './AuthModal'
import { Button } from './Button'
import { getStoredUser } from '../routes/authRouting'
import { EmployerFooter } from '../employer/components/EmployerFooter'
import { api } from '../services/api'
import { useApiResource } from '../hooks/useApiResource'
import { getCandidateProfileCompletion, getJobAlerts } from '../utils/candidateActivity'
import { getSavedJobs } from '../utils/savedJobs'
import { useSiteBranding } from '../utils/siteBranding'
import { useSocialMediaLinks } from '../utils/socialMediaLinks'

const navItems = [
  { label: 'Home', to: '/' },
  { label: 'Jobs', to: '/jobs' },
  { label: 'Internship Course', to: '/internship-course' },
  { label: 'Companies', to: '/companies' },
  { label: 'Freelancer', to: '/freelancer' },
  { label: 'Candidates', to: '/candidate-dashboard' },
]

const publicNavItems = [
  { label: 'Jobs', to: '/jobs' },
  { label: 'Freelancer', to: '/freelancer' },
  { label: 'Courses', to: '/jobs', offer: true },
]

const recruiterDashboardPath = '/recruiter-dashboard'
const recruiterProfilePath = '/recruiter-profile'
const liveLocationRoles = ['Candidate', 'users', 'recruiter']

export function Layout() {
  const [open, setOpen] = useState(false)
  const [profileOpen, setProfileOpen] = useState(false)
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [notifications, setNotifications] = useState([])
  const [notificationsLoading, setNotificationsLoading] = useState(false)
  const [clearedNotificationIds, setClearedNotificationIds] = useState([])
  const [user, setUser] = useState(() => getStoredUser())
  const [newsletterEmail, setNewsletterEmail] = useState('')
  const [newsletterStatus, setNewsletterStatus] = useState({ type: '', message: '' })
  const [newsletterLoading, setNewsletterLoading] = useState(false)
  const [appBannerOpen, setAppBannerOpen] = useState(true)

  useEffect(() => {
    if (!appBannerOpen) return

    const timeoutId = window.setTimeout(() => setAppBannerOpen(false), 3000)
    return () => window.clearTimeout(timeoutId)
  }, [appBannerOpen])

  const [authModalMode, setAuthModalMode] = useState('')
  const [showCompaniesNav, setShowCompaniesNav] = useState(false)
  const [headerSearch, setHeaderSearch] = useState('')
  const branding = useSiteBranding()
  const socialLinks = useSocialMediaLinks()
  const location = useLocation()
  const navigate = useNavigate()
  const isCandidate = user?.role === 'Candidate'
  const isUserAccount = ['Candidate', 'users'].includes(user?.role)
  const isRecruiterAccount = user?.role === 'recruiter'
  const hideFooterOnMobile = location.pathname === '/auth' || location.pathname === '/jobs' || location.pathname.startsWith('/jobs/') || location.pathname.startsWith('/job-listings-') || location.pathname.startsWith('/jobs-in-') || location.pathname.startsWith('/company-jobs-') || location.pathname.startsWith('/freelance-project-listings-') || location.pathname === '/candidate-dashboard' || location.pathname.startsWith('/candidate-')
  const visibleNavItems = navItems
    .filter((item) => item.label !== 'Companies' || showCompaniesNav)
    .filter((item) => !isUserAccount || item.label !== 'Recruiter')
    .map((item) => {
      if (isUserAccount && item.label === 'Candidates') return { ...item, label: 'Accounts' }
      if (isRecruiterAccount && item.label === 'Recruiter') return { ...item, to: recruiterDashboardPath }
      return item
    })
  const mobileNavItems = visibleNavItems.filter((item) => !['Freelancer', 'Recruiter'].includes(item.label))
  const publicHeaderLinks = [
    { label: 'Home', to: '/' },
    { label: 'Find Jobs', to: '/jobs' },
    { label: 'Internship Course', to: '/internship-course', badge: 'Video' },
    ...(showCompaniesNav ? [{ label: 'Companies', to: '/companies' }] : []),
    { label: 'Freelance Projects', to: '/freelancer/projects', badge: 'New' },
    { label: 'Candidates', to: isUserAccount ? '/candidate-dashboard' : '/auth', caption: 'Candidates' },
  ]

  useEffect(() => {
    setUser(getStoredUser())
    setOpen(false)
    setProfileOpen(false)
    setNotificationsOpen(false)
  }, [location.pathname])

  useEffect(() => {
    let mounted = true

    api
      .companyProfiles()
      .then((payload) => {
        if (!mounted) return
        const companies = Array.isArray(payload.data) ? payload.data : []
        const completeCompanies = companies.filter((company) => (
          company?.name
          && (company?.status || 'Active') !== 'Rejected'
        ))
        setShowCompaniesNav(completeCompanies.length >= 50)
      })
      .catch(() => {
        if (mounted) setShowCompaniesNav(false)
      })

    return () => {
      mounted = false
    }
  }, [])

  useEffect(() => {
    if (!user?.email || !user?.role) {
      setNotifications([])
      setClearedNotificationIds([])
      return
    }

    let mounted = true
    const key = getRoleNotificationClearKey(user)
    const loadNotifications = async () => {
      setNotificationsLoading(true)
      try {
        const roleNotifications = await buildRoleNotifications(user)
        const clearedIds = JSON.parse(localStorage.getItem(key) || '[]')
        if (!mounted) return
        setClearedNotificationIds(clearedIds)
        setNotifications(roleNotifications.filter((item) => !clearedIds.includes(item.id)))
      } catch {
        if (mounted) setNotifications([])
      } finally {
        if (mounted) setNotificationsLoading(false)
      }
    }

    loadNotifications()
    window.addEventListener('focus', loadNotifications)
    window.addEventListener('candidateActivityChanged', loadNotifications)
    window.addEventListener('savedJobsChanged', loadNotifications)
    window.addEventListener('recruiter-wallet-updated', loadNotifications)

    return () => {
      mounted = false
      window.removeEventListener('focus', loadNotifications)
      window.removeEventListener('candidateActivityChanged', loadNotifications)
      window.removeEventListener('savedJobsChanged', loadNotifications)
      window.removeEventListener('recruiter-wallet-updated', loadNotifications)
    }
  }, [user?.email, user?.role])

  useEffect(() => {
    if (!user?.role || !liveLocationRoles.includes(user.role)) return undefined

    const captureLocation = () => {
      const basePayload = {
        loginTime: new Date().toISOString(),
        deviceInfo: navigator.userAgent || '',
      }

      if (!navigator.geolocation) {
        api.trackUserLocation({ ...basePayload, locationStatus: 'unavailable' }).catch(() => {})
        return
      }

      navigator.geolocation.getCurrentPosition(
        (position) => {
          api.trackUserLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
            accuracy: position.coords.accuracy,
            heading: position.coords.heading,
            speed: position.coords.speed,
            ...basePayload,
            locationStatus: 'allowed',
          }).catch(() => {})
        },
        (error) => {
          api.trackUserLocation({
            ...basePayload,
            locationStatus: error.code === error.PERMISSION_DENIED ? 'denied' : 'unavailable',
          }).catch(() => {})
        },
        {
          enableHighAccuracy: true,
          maximumAge: 15000,
          timeout: 12000,
        },
      )
    }

    captureLocation()
    const interval = window.setInterval(captureLocation, 30000)
    return () => window.clearInterval(interval)
  }, [user?.email, user?.role])

  const clearNotifications = () => {
    if (!user?.email) return
    const nextIds = [...new Set([...clearedNotificationIds, ...notifications.map((item) => item.id)])]
    localStorage.setItem(getRoleNotificationClearKey(user), JSON.stringify(nextIds))
    setClearedNotificationIds(nextIds)
    setNotifications([])
  }

  const logout = () => {
    localStorage.removeItem('authToken')
    localStorage.removeItem('authUser')
    localStorage.removeItem('authExpiresAt')
    setUser(null)
    setProfileOpen(false)
    navigate('/auth')
  }

  const subscribeNewsletter = async (event) => {
    event.preventDefault()
    const email = newsletterEmail.trim().toLowerCase()
    setNewsletterStatus({ type: '', message: '' })

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setNewsletterStatus({ type: 'error', message: 'Please enter a valid email address.' })
      return
    }

    setNewsletterLoading(true)
    try {
      const payload = await api.subscribeNewsletter({
        email,
        source: user?.role ? `${user.role} footer` : 'public footer',
        topics: ['Hiring insights', 'Latest jobs', 'Recruiter updates'],
      })
      setNewsletterEmail('')
      setNewsletterStatus({ type: 'success', message: payload.message || 'Subscribed successfully. You will receive hiring updates.' })
    } catch (error) {
      setNewsletterStatus({ type: 'error', message: error.message || 'Subscription failed. Please try again.' })
    } finally {
      setNewsletterLoading(false)
    }
  }

  const openAuthModal = (mode) => {
    setAuthModalMode(mode)
    setOpen(false)
  }

  const handleHeaderLinkClick = () => {
    window.requestAnimationFrame(() => window.scrollTo({ top: 0, behavior: 'smooth' }))
  }

  const submitHeaderSearch = (event) => {
    event.preventDefault()
    const query = headerSearch.trim()
    navigate(query ? `/jobs?q=${encodeURIComponent(query)}` : '/jobs')
    handleHeaderLinkClick()
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      <header className="sticky top-0 z-50 bg-white/95 px-2 py-2 shadow-sm backdrop-blur sm:px-4">
        <div className="mx-auto max-w-[1560px] rounded-[14px] bg-white shadow-xl shadow-slate-200/70">
          <nav className="flex min-h-[72px] items-center justify-between gap-3 px-3 sm:px-5 lg:gap-5">
            <Link className="flex w-32 shrink-0 items-center font-bold text-[#ff8a00] sm:w-40" onClick={handleHeaderLinkClick} to="/">
              {branding.logoUrl ? (
                <img className="h-10 w-full object-contain object-left sm:h-12" src={branding.logoUrl} alt={branding.siteName || 'INSEET'} />
              ) : (
                <>
                  <span className="grid h-12 w-12 place-items-center rounded-[7px] bg-[#0057B8] text-white"><BriefcaseBusiness size={22} /></span>
                  <span className="ml-3 text-xl text-[#ff8a00]">{branding.siteName || 'INSEET'}</span>
                </>
              )}
            </Link>

            <div className="hidden flex-1 items-center justify-center gap-4 xl:flex">
              {publicHeaderLinks.map((item) => (
                <NavLink
                  className={({ isActive }) =>
                    `group relative inline-flex min-h-[50px] items-center gap-1.5 text-[13px] font-bold transition ${
                      isActive ? 'text-[#0057B8]' : 'text-slate-950 hover:text-[#0057B8]'
                    }`
                  }
                  key={item.label}
                  onClick={handleHeaderLinkClick}
                  to={item.to}
                >
                  {({ isActive }) => (
                    <>
                      <span className="leading-5">
                        {item.label}
                        {item.caption && <span className="block text-xs font-semibold text-slate-500">{item.caption}</span>}
                      </span>
                      {item.badge && <span className="rounded-full bg-blue-100 px-2 py-0.5 text-[10px] font-black text-blue-700">{item.badge}</span>}
                      {item.dropdown && <ChevronDown size={14} />}
                      <span className={`absolute bottom-0 left-0 h-1 rounded-full bg-[#0057B8] transition-all ${isActive ? 'w-full' : 'w-0 group-hover:w-full'}`} />
                    </>
                  )}
                </NavLink>
              ))}
            </div>

            <form className="hidden h-10 w-[250px] shrink-0 items-center gap-2 rounded-full border border-slate-200 bg-white px-4 shadow-sm xl:flex" onSubmit={submitHeaderSearch}>
              <button className="grid h-8 w-8 shrink-0 place-items-center rounded-full text-slate-400 transition hover:bg-slate-50 hover:text-[#0057B8]" type="submit" aria-label="Search jobs">
                <Search size={19} />
              </button>
              <input
                className="min-w-0 flex-1 bg-transparent text-sm font-semibold outline-none placeholder:text-slate-400"
                onChange={(event) => setHeaderSearch(event.target.value)}
                placeholder="Search jobs, skills or companies"
                value={headerSearch}
              />
            </form>

            <div className="hidden shrink-0 items-center gap-2 xl:flex">
            {isUserAccount ? (
              <>
                <RoleNotificationBell loading={notificationsLoading} notifications={notifications} onClear={clearNotifications} open={notificationsOpen} setOpen={setNotificationsOpen} setProfileOpen={setProfileOpen} user={user} />
                <CandidateProfileMenu logout={logout} open={profileOpen} setOpen={setProfileOpen} user={user} />
              </>
            ) : isRecruiterAccount ? (
              <>
                <RoleNotificationBell loading={notificationsLoading} notifications={notifications} onClear={clearNotifications} open={notificationsOpen} setOpen={setNotificationsOpen} setProfileOpen={setProfileOpen} user={user} />
                <CompanyProfileMenu logout={logout} open={profileOpen} setOpen={setProfileOpen} user={user} />
              </>
            ) : (
              <>
                <button className="inline-flex min-h-10 items-center justify-center rounded-[7px] border border-[#0057B8] bg-[white] px-4 text-sm font-bold text-[#0057B8] transition hover:bg-blue-50" onClick={() => openAuthModal('login')} type="button">
                  Login
                </button>
                <button className="inline-flex min-h-10 items-center justify-center rounded-[7px] bg-[#ff8a00] px-4 text-sm font-bold text-white shadow-lg shadow-orange-100 transition hover:bg-[#e87500]" onClick={() => openAuthModal('register')} type="button">
                  Register
                </button>
                <Link className="inline-flex min-h-10 items-center gap-2 whitespace-nowrap rounded-[7px] bg-[#0057B8] px-4 text-[13px] font-bold text-white shadow-lg shadow-blue-100" onClick={handleHeaderLinkClick} to="/recruiter">
                  <BriefcaseBusiness size={19} />
                  <span>
                    For Employers
                    <span className="block text-xs font-semibold text-blue-100">Post Jobs Free</span>
                  </span>
                  <ArrowRight size={17} />
                </Link>
              </>
            )}
            </div>

            <button
              aria-label={open ? 'Close menu' : 'Open menu'}
              aria-expanded={open}
              className="grid h-10 w-10 shrink-0 place-items-center rounded-[7px] bg-[#0057B8] text-white shadow-lg shadow-blue-100 xl:hidden"
              onClick={() => setOpen((value) => !value)}
              type="button"
            >
              {open ? <X size={20} /> : <Menu size={20} />}
            </button>
          </nav>
        </div>

        <div className={`xl:hidden ${open ? 'pointer-events-auto' : 'pointer-events-none'}`}>
          <button aria-label="Close menu overlay" className={`fixed inset-0 z-[80] bg-slate-950/35 transition-opacity duration-300 ${open ? 'opacity-100' : 'opacity-0'}`} onClick={() => setOpen(false)} type="button" />
          <aside inert={!open} className={`fixed inset-y-0 right-0 z-[90] h-dvh w-80 max-w-[86vw] overflow-y-auto border-l border-[#0057B8]/10 bg-white px-4 py-4 shadow-2xl shadow-[#0057B8]/20 transition-transform duration-300 ease-out ${open ? 'translate-x-0' : 'translate-x-full'}`}>
              <div className="mb-4 flex items-center justify-between gap-3 rounded-[7px] bg-[linear-gradient(135deg,#eef7ff,#fff4e6)] p-3">
                <span className="text-sm font-black text-slate-950">Menu</span>
                <button aria-label="Close menu" className="grid h-9 w-9 place-items-center rounded-[7px] bg-[white] text-slate-700 shadow-sm ring-1 ring-slate-200 transition hover:text-[#ff8a00]" onClick={() => setOpen(false)} type="button">
                  <X size={18} />
                </button>
              </div>
              <div className="grid gap-2">
              {mobileNavItems.map((item) => (
                <NavLink className={({ isActive }) => `flex items-center justify-between gap-3 rounded-[7px] px-4 py-3 text-sm font-black transition ${isActive ? 'bg-orange-50 text-[#ff8a00]' : 'text-slate-700 hover:bg-slate-50 hover:text-[#ff8a00]'}`} key={item.label} onClick={() => setOpen(false)} to={item.to}>
                  <span>{item.label}</span>
                  {item.label === 'Recruiter' && (
                    <span className="recruiter-offer-badge rounded-[7px] bg-rose-600 px-2 py-1 text-[10px] font-black uppercase tracking-wide text-white">
                      New Recruiter Offer
                    </span>
                  )}
                </NavLink>
              ))}
              {isUserAccount ? (
                <div className="grid gap-2 pt-2">
                  <div className="flex items-center gap-3 rounded-[7px] bg-blue-50 px-4 py-3 text-sm font-black text-slate-950">
                    <span className="grid h-9 w-9 place-items-center rounded-[7px] bg-blue-600 text-white">
                      <UserRound size={17} />
                    </span>
                    {user.name || 'Candidate'}
                  </div>
                  <MobileNotifications loading={notificationsLoading} notifications={notifications} onClear={clearNotifications} user={user} />
                  {isCandidate && <Button onClick={() => setOpen(false)} to="/candidate-profile" variant="secondary">Profile</Button>}
                  <button className="inline-flex min-h-11 items-center justify-center rounded-[7px] bg-rose-50 px-5 py-2.5 text-sm font-semibold text-rose-600 transition hover:bg-rose-100" onClick={logout} type="button">
                    Logout
                  </button>
                </div>
              ) : isRecruiterAccount ? (
                <div className="grid gap-2 pt-2">
                  <div className="flex items-center gap-3 rounded-[7px] bg-blue-50 px-4 py-3 text-sm font-black text-slate-950">
                    <span className="grid h-9 w-9 place-items-center rounded-[7px] bg-blue-600 text-white">
                      <UserRound size={17} />
                    </span>
                    {user.name || 'Company'}
                  </div>
                  <MobileNotifications loading={notificationsLoading} notifications={notifications} onClear={clearNotifications} user={user} />
                  <Button onClick={() => setOpen(false)} to={recruiterProfilePath} variant="secondary">Profile</Button>
                  <Button onClick={() => setOpen(false)} to={recruiterDashboardPath} variant="secondary">Dashboard</Button>
                  <button className="inline-flex min-h-11 items-center justify-center rounded-[7px] bg-rose-50 px-5 py-2.5 text-sm font-semibold text-rose-600 transition hover:bg-rose-100" onClick={logout} type="button">
                    Logout
                  </button>
                </div>
              ) : (
                <>
                  <div className="grid gap-2 pt-2">
                    <button className="inline-flex min-h-11 items-center justify-center rounded-[7px] border border-[#ff8a00] bg-[white] px-4 text-sm font-black text-black transition hover:bg-[#fff4e6]" onClick={() => openAuthModal('login')} type="button">Login</button>
                    <button className="inline-flex min-h-11 items-center justify-center rounded-[7px] bg-[#ff8a00] px-4 text-sm font-black text-white" onClick={() => openAuthModal('register')} type="button">Register</button>
                  </div>
