                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <p className="rounded-[7px] bg-slate-50 p-5 text-sm font-semibold text-slate-500">No applied jobs yet.</p>
        )}
      </Panel>
    </DashboardShell>
  )
}

