                  <tr className="hover:bg-blue-50/40" key={job._id || job.id || `${job.title}-${index}`}>
                    <td className="px-4 py-3 font-black text-slate-500">#{index + 1}</td>
                    <td className="px-4 py-3 font-black text-slate-950">{job.title || '-'}</td>
