function JobPreviewModal({ form, onClose }) {
  const salaryRange = formatSalaryRange(form.salaryMin, form.salaryMax) || form.salary

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4">
      <div className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-[7px] bg-white p-6 shadow-2xl">
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-sm font-black uppercase tracking-wide text-blue-600">Job Preview</p>
            <h2 className="mt-2 text-3xl font-black text-slate-950">{form.title || 'Job title'}</h2>
            <p className="mt-2 font-semibold text-slate-500">{form.company || 'Company'} · {buildStateCountryLocation(form) || 'Location'}</p>
          </div>
          <button className="grid h-10 w-10 place-items-center rounded-[7px] bg-slate-100" onClick={onClose} type="button"><X size={18} /></button>
        </div>
        <div className="mt-6 grid gap-4 text-sm font-semibold text-slate-600">
          <p><strong>Department:</strong> {form.department || 'Not added'}</p>
          <p><strong>Salary:</strong> {salaryRange || 'Not disclosed'}</p>
          <p><strong>Experience:</strong> {form.experience}</p>
          <p><strong>Work:</strong> {form.type} / {form.workMode}</p>
          <p><strong>Deadline:</strong> {form.deadline || 'Not added'}</p>
          <div><strong>Skills:</strong> <div className="mt-2 flex flex-wrap gap-2">{form.skills.map((skill) => <span className="rounded-[7px] bg-blue-50 px-3 py-1 text-xs font-black text-blue-700" key={skill}>{skill}</span>)}</div></div>
          <p className="whitespace-pre-line"><strong>Description:</strong><br />{form.description || 'Not added'}</p>
        </div>
      </div>
    </div>
  )
}

function SummaryLine({ label, value }) {
  return (
    <div className="rounded-[7px] border border-slate-100 bg-white p-3">
      <p className="text-[11px] font-black uppercase tracking-wide text-slate-400">{label}</p>
      <p className="mt-1 break-words text-sm font-black text-slate-800">{value}</p>
    </div>
  )
}

function PackageSelectionModal({ activePackage, onChoose, onClose, packages }) {
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4">
      <div className="max-h-[90vh] w-full max-w-5xl overflow-y-auto rounded-[7px] bg-white p-6 shadow-2xl">
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-sm font-black uppercase tracking-wide text-blue-600">Choose Package</p>
            <h2 className="mt-2 text-3xl font-black text-slate-950">{activePackage ? 'Wallet coins are required to post this job' : 'Activate package and submit job'}</h2>
            {activePackage && <p className="mt-2 text-sm font-bold text-slate-500">Current wallet: {activePackage.coinBalance || 0} coins. One job requires {activePackage.packageSnapshot?.coinPerJob || 10} coins.</p>}
          </div>
          <button className="grid h-10 w-10 place-items-center rounded-[7px] bg-slate-100" onClick={onClose} type="button"><X size={18} /></button>
        </div>
        <div className="mt-6 grid gap-4 lg:grid-cols-3">
          {packages.map((plan) => (
            <div className="rounded-[7px] border border-slate-200 p-5" key={plan._id || plan.name}>
              <h3 className="text-xl font-black text-slate-950">{plan.name}</h3>
              <p className="mt-2 text-2xl font-black text-blue-600">{plan.price}</p>
              <p className="mt-2 text-sm font-bold text-slate-500">{plan.jobLimit || 1} jobs / {getPlanValidityDays(plan)} days / {plan.discountPercent || 0}% discount</p>
              <p className="mt-1 text-xs font-black uppercase tracking-wide text-slate-400">100 rupees = 10 coins / {plan.coinPerJob || 10} coins per job</p>
              {getPackageAmount(plan) > 0 && (
                <div className="mt-4 grid gap-2 rounded-[7px] bg-slate-50 p-3 text-xs font-black text-slate-600">
                  <span>Payment options</span>
                  <span className="rounded-[7px] bg-white px-3 py-2">UPI / QR Payment</span>
                  <span className="rounded-[7px] bg-white px-3 py-2">Card / Net Banking</span>
                </div>
              )}
              <button
                className="mt-5 w-full rounded-[7px] bg-blue-600 px-4 py-3 text-sm font-black text-white disabled:bg-slate-300"
                disabled={isEnterprisePlan(plan)}
                onClick={() => onChoose(plan)}
                type="button"
              >
                {isEnterprisePlan(plan) ? 'Request Callback from Pricing' : getPackageAmount(plan) > 0 ? 'Pay & Activate' : 'Activate Free Package'}
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { BriefcaseBusiness, Download, FileText, Mail, Search, Sparkles, UsersRound } from 'lucide-react'
import { Button } from '../components/Button'
import { api } from '../services/api'
import { DashboardShell, Panel } from './CandidateDashboard'

export function RecruiterFindResumePage() {
  const [query, setQuery] = useState('')
  const [activeFilter, setActiveFilter] = useState('all')
  const [resumes, setResumes] = useState([])
  const [jobs, setJobs] = useState([])

  useEffect(() => {
    let ignore = false

    Promise.all([api.list('resumes'), api.list('candidates'), api.jobListings('?sort=-createdAt')])
      .then(([resumePayload, candidatePayload, jobsPayload]) => {
        if (ignore) return

        const uploaded = Array.isArray(resumePayload.data) ? resumePayload.data : []
        const leads = Array.isArray(candidatePayload.data)
          ? candidatePayload.data.map((candidate) => ({ ...candidate, source: 'Lead Resume' }))
          : []
        setResumes([...uploaded, ...leads])
        setJobs(Array.isArray(jobsPayload.data) ? jobsPayload.data : [])
      })
      .catch(() => {
        if (!ignore) {
          setResumes([])
          setJobs([])
        }
      })

    return () => {
      ignore = true
    }
  }, [])

  const matchingJobs = useMemo(() => {
    const search = normalize(query)
    if (!search) return jobs

    return jobs.filter((job) => normalize([job.title, job.company, job.department, job.location, ...(job.skills || [])].join(' ')).includes(search))
  }, [query])

  const rankedResumes = useMemo(() => rankResumes(resumes, matchingJobs, query), [matchingJobs, query, resumes])
  const searchedResumes = useMemo(() => {
    if (!normalize(query)) return rankedResumes
    return rankedResumes.filter((resume) => resume.score > 0 || resume.queryMatch)
  }, [query, rankedResumes])
  const visibleResumes = useMemo(() => {
    if (activeFilter === 'best') return searchedResumes.filter((resume) => resume.score >= 2)
    if (activeFilter === 'lead') return searchedResumes.filter((resume) => resume.source === 'Lead Resume')
    if (activeFilter === 'jobs') return searchedResumes.filter((resume) => resume.score > 0)
    return searchedResumes
  }, [activeFilter, searchedResumes])

  const bestMatches = searchedResumes.filter((resume) => resume.score >= 2)
  const leadResumes = searchedResumes.filter((resume) => resume.source === 'Lead Resume')

  return (
    <DashboardShell title="Find Resume" subtitle="Search by job title, company, location, or skills and review matching resumes for that role.">
      <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-4">
        <FilterMetric active={activeFilter === 'all'} icon={FileText} label="Available Resumes" onClick={() => setActiveFilter('all')} value={String(searchedResumes.length)} />
        <FilterMetric active={activeFilter === 'jobs'} icon={BriefcaseBusiness} label="Matched Jobs" onClick={() => setActiveFilter('jobs')} value={String(matchingJobs.length)} />
        <FilterMetric active={activeFilter === 'best'} icon={Sparkles} label="Best Matches" onClick={() => setActiveFilter('best')} value={String(bestMatches.length)} />
        <FilterMetric active={activeFilter === 'lead'} icon={UsersRound} label="Lead Resumes" onClick={() => setActiveFilter('lead')} value={String(leadResumes.length)} />
      </div>

      <div className="mt-6 grid gap-6">
        <Panel title="Resume Results">
          <label className="mb-5 flex items-center gap-3 rounded-[7px] border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-500">
            <Search className="text-blue-600" size={18} />
              <input
                className="w-full bg-transparent outline-none"
                onChange={(event) => {
                  setQuery(event.target.value)
                  setActiveFilter('all')
                }}
                placeholder="Search job, skill, company..."
                value={query}
              />
            </label>
          <div className="grid gap-3">
            {visibleResumes.length ? visibleResumes.map((resume) => (
              <div className="grid gap-4 rounded-[7px] bg-slate-50 p-4 xl:grid-cols-[1fr_auto] xl:items-center" key={`${resume.email}-${resume.name}`}>
                <div>
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="font-black text-slate-950">{resume.name}</p>
                    <span className="rounded-[7px] bg-blue-50 px-2.5 py-1 text-xs font-black text-blue-700">{resume.matchLabel}</span>
                    <span className="rounded-[7px] bg-white px-2.5 py-1 text-xs font-black text-slate-600 ring-1 ring-slate-200">{resume.source || 'Resume'}</span>
                  </div>
                  <p className="mt-1 text-sm font-semibold text-slate-600">{resume.role || 'Candidate'} - {resume.experience || 'Experience not added'}</p>
                  <p className="mt-2 flex items-center gap-2 text-sm text-slate-500"><Mail size={15} /> {resume.email || 'Email not added'}</p>
                  <div className="mt-3 flex flex-wrap gap-2">
                    {normalizeSkills(resume.skills).map((skill) => (
                      <span className="rounded-[7px] bg-white px-3 py-1 text-xs font-black text-slate-600 ring-1 ring-slate-200" key={skill}>{skill}</span>
                    ))}
                  </div>
                </div>
                <div className="flex flex-wrap gap-2 xl:justify-end">
                  <Button variant="secondary">View Resume</Button>
                  <Button>
                    <Download size={17} />
                    Download
                  </Button>
                </div>
              </div>
            )) : (
              <p className="rounded-[7px] bg-slate-50 p-5 text-sm font-semibold text-slate-500">No resumes found for this search.</p>
            )}
          </div>
        </Panel>
      </div>
    </DashboardShell>
  )
}

function FilterMetric({ active, icon: Icon, label, onClick, value }) {
  return (
    <button
      className={`rounded-[7px] border p-5 text-left shadow-sm transition hover:-translate-y-0.5 ${
        active ? 'border-blue-200 bg-blue-50 shadow-blue-100' : 'border-slate-200 bg-white hover:bg-slate-50'
      }`}
      onClick={onClick}
      type="button"
    >
      <Icon className="text-blue-600" size={24} />
      <p className="mt-5 text-3xl font-black text-slate-950">{value}</p>
      <p className="mt-1 text-sm font-medium text-slate-500">{label}</p>
    </button>
  )
}

function rankResumes(items, matchedJobs, query) {
  const jobTerms = matchedJobs
    .flatMap((job) => [job.title, job.department, job.company, job.location, ...(job.skills || [])])
    .map(normalize)
    .filter(Boolean)
  const queryTerm = normalize(query)

  return items
    .map((resume) => {
      const resumeText = normalize([resume.name, resume.role, resume.location, resume.experience, ...normalizeSkills(resume.skills)].join(' '))
      const queryMatch = Boolean(queryTerm && resumeText.includes(queryTerm))
      const score = jobTerms.reduce((total, term) => total + (resumeText.includes(term) ? 1 : 0), 0) + (queryMatch ? 2 : 0)

      return {
        ...resume,
        score,
        queryMatch,
        matchLabel: score >= 3 ? 'Strong match' : score >= 1 ? 'Good match' : 'Related profile',
      }
    })
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
}

function normalize(value = '') {
  return String(value).toLowerCase().trim()
}

function normalizeSkills(skills = []) {
  if (Array.isArray(skills)) return skills.filter(Boolean)
  return String(skills)
    .split(',')
    .map((skill) => skill.trim())
    .filter(Boolean)
}

import { useEffect, useState } from 'react'
import { CheckCircle2, CreditCard, ShieldCheck, Sparkles } from 'lucide-react'
import { api } from '../services/api'
import { DashboardShell, Panel } from './CandidateDashboard'
import { fetchPricingPackages, getPricingPackages, PRICING_PACKAGES_KEY } from '../utils/pricingPackages'
import { showMessageToast, showToast } from '../utils/toast'

function getStoredRecruiter() {
  try {
    return JSON.parse(localStorage.getItem('authUser') || 'null')
  } catch {
    return null
  }
}

function getPackageAmount(plan) {
  const amount = Number(String(plan?.price || '').replace(/[^\d.]/g, ''))
  return Number.isFinite(amount) ? amount : 0
}

function getPackageKey(plan) {
  return String(plan?.key || plan?.name || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
}

function isFreeTrialPlan(plan) {
  const key = getPackageKey(plan)
  return key === 'starter' || key === 'free-trial'
}

function isEnterprisePlan(plan) {
  const key = getPackageKey(plan)
  return key === 'enterprise' || String(plan?.price || '').trim().toLowerCase() === 'custom'
}

function getPlanValidityDays(plan) {
  return isFreeTrialPlan(plan) ? 3 : Number(plan?.validityDays || 30)
}

function getPlanButtonLabel(plan) {
  if (getPackageAmount(plan) > 0) return 'Pay & Activate'
  if (isEnterprisePlan(plan)) return 'Request Callback'
  if (isFreeTrialPlan(plan)) return 'Start Free Trial'
  return plan?.buttonLabel || 'Start Hiring'
}

function getPackageCoins(plan) {
  const amount = getPackageAmount(plan)
  const discount = Number(plan?.discountPercent || 0)
  const payable = Math.max(0, amount - (amount * discount) / 100)
  const amountCoins = Math.floor(payable / 100) * 10
  const coinPerJob = Number(plan?.coinPerJob || 10)
  const jobLimit = Number(plan?.jobLimit || 1)

  return Math.max(amountCoins, coinPerJob, jobLimit * coinPerJob)
}

function buildPackageRequest(recruiter, plan) {
  const payload = {
    recruiterEmail: recruiter.email,
    recruiterName: recruiter.name,
    packageKey: plan.key || '',
    packageName: plan.name || '',
  }
  const packageId = plan._id || plan.id
  if (packageId && /^[a-f\d]{24}$/i.test(String(packageId))) {
    payload.packageId = packageId
  }
  return payload
}

function isCurrentPackage(plan, activePackage) {
  if (!activePackage || !plan) return false

  const hasActivePackage = Boolean(activePackage.packageId || activePackage.packageSnapshot?.name)
  if (!hasActivePackage) return false

  const activeId = activePackage.packageId ? String(activePackage.packageId) : ''
  const planId = plan._id ? String(plan._id) : ''
  if (activeId && planId) return activeId === planId

  const activeName = String(activePackage.packageSnapshot?.name || '').trim().toLowerCase()
  const planName = String(plan.name || '').trim().toLowerCase()
  const planKey = String(plan.key || '').trim().toLowerCase()
  return Boolean(activeName && planName && activeName === planName)
    || Boolean(activeName && planKey && activeName.replace(/[^a-z0-9]+/g, '-') === planKey)
}

function loadRazorpayCheckout() {
  if (window.Razorpay) return Promise.resolve(true)

  return new Promise((resolve) => {
    const script = document.createElement('script')
    script.src = 'https://checkout.razorpay.com/v1/checkout.js'
    script.onload = () => resolve(true)
    script.onerror = () => resolve(false)
    document.body.appendChild(script)
  })
}

function PaymentDetails({ details }) {
  if (!details) return null

  const payment = details.payment || {}

  return (
    <div className="mb-5 rounded-[7px] border border-teal-200 bg-teal-50 p-5">
      <p className="text-xs font-black uppercase tracking-wide text-teal-700">Payment Details</p>
      <div className="mt-3 grid gap-3 text-sm font-bold text-teal-900 sm:grid-cols-2 lg:grid-cols-4">
        <div><span className="block text-xs uppercase text-teal-600">Invoice</span>{payment.invoiceNo || 'Pending'}</div>
        <div><span className="block text-xs uppercase text-teal-600">Amount</span>{payment.amount || `INR ${details.amount || 0}`}</div>
        <div><span className="block text-xs uppercase text-teal-600">Gateway</span>{payment.gateway || 'Razorpay'}</div>
        <div><span className="block text-xs uppercase text-teal-600">Payment ID</span>{payment.razorpayPaymentId || details.razorpayPaymentId || 'Pending'}</div>
      </div>
    </div>
  )
}

export function RecruiterPricingPage() {
  const recruiter = getStoredRecruiter()
  const [plans, setPlans] = useState(() => getPricingPackages())
  const [activePackage, setActivePackage] = useState(null)
  const [message, setMessage] = useState('')
  const [paymentPlan, setPaymentPlan] = useState(null)
  const [paymentDetails, setPaymentDetails] = useState(null)
  const [paymentProcessing, setPaymentProcessing] = useState(false)
  const [coinQuantity, setCoinQuantity] = useState(50)
  const [coinBuying, setCoinBuying] = useState(false)
  const [callbackPlan, setCallbackPlan] = useState(null)

  const notify = (text, type) => {
    setMessage('')
    if (text) showMessageToast(text, type ? { type } : {})
  }

  useEffect(() => {
    const syncPlans = () => {
      fetchPricingPackages({ activeOnly: true })
        .then(setPlans)
        .catch(() => setPlans(getPricingPackages()))
    }
    const syncFromStorage = (event) => {
      if (!event.key || event.key === PRICING_PACKAGES_KEY || event.key === `${PRICING_PACKAGES_KEY}:updatedAt`) {
        syncPlans()
      }
    }

    window.addEventListener('pricing-packages-updated', syncPlans)
    window.addEventListener('storage', syncFromStorage)
    window.addEventListener('focus', syncPlans)
    document.addEventListener('visibilitychange', syncPlans)
    syncPlans()

    return () => {
      window.removeEventListener('pricing-packages-updated', syncPlans)
      window.removeEventListener('storage', syncFromStorage)
      window.removeEventListener('focus', syncPlans)
      document.removeEventListener('visibilitychange', syncPlans)
    }
  }, [])

  const loadActivePackage = () => {
    if (!recruiter?.email) return

    api
      .currentRecruiterPackage(recruiter.email)
      .then((payload) => setActivePackage(payload.data || null))
      .catch(() => setActivePackage(null))
  }

  useEffect(() => {
    loadActivePackage()
  }, [recruiter?.email])

  useEffect(() => {
    const syncWallet = () => loadActivePackage()

    window.addEventListener('focus', syncWallet)
    window.addEventListener('recruiter-wallet-updated', syncWallet)

    return () => {
      window.removeEventListener('focus', syncWallet)
      window.removeEventListener('recruiter-wallet-updated', syncWallet)
    }
  }, [recruiter?.email])

  const activatePackage = async (plan) => {
    if (!recruiter?.email) {
      notify('Please login as recruiter to activate a package.', 'error')
      return
    }

    try {
      const payload = await api.activateRecruiterPackage({
        ...buildPackageRequest(recruiter, plan),
      })
      setActivePackage(payload.data)
      window.dispatchEvent(new Event('recruiter-wallet-updated'))
      notify(`${plan.name} package activated successfully.`, 'success')
    } catch (error) {
      notify(error.message, 'error')
    }
  }

  const startRazorpayPayment = async ({ amount, description, name, onSuccess, orderPayload }) => {
    setPaymentProcessing(true)

    try {
      const checkoutLoaded = await loadRazorpayCheckout()
      if (!checkoutLoaded) throw new Error('Razorpay checkout could not be loaded. Please check internet connection.')

      const orderResponse = await api.createRecruiterRazorpayOrder(orderPayload)
      const order = orderResponse.data

      await new Promise((resolve, reject) => {
        const checkout = new window.Razorpay({
          key: order.keyId,
          amount: order.amount * 100,
          currency: order.currency || 'INR',
          name: order.companyName || 'INSEET',
          description,
          order_id: order.orderId,
          prefill: {
            name: recruiter?.name || '',
            email: recruiter?.email || '',
          },
          theme: {
            color: order.themeColor || '#2563eb',
          },
          handler: async (response) => {
            try {
              const verified = await api.verifyRecruiterRazorpayPayment({
                recruiterEmail: recruiter.email,
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
              })
              await onSuccess(verified)
              setPaymentDetails({
                amount,
                name,
                razorpayPaymentId: response.razorpay_payment_id,
                payment: verified.data?.payment,
              })
              notify(verified.message || 'Payment successful.', 'success')
              resolve()
            } catch (error) {
              reject(error)
            }
          },
          modal: {
            ondismiss: () => reject(new Error('Payment cancelled.')),
          },
        })

        checkout.open()
      })
    } catch (error) {
      notify(error.message || 'Payment failed.', 'error')
    } finally {
      setPaymentProcessing(false)
    }
  }

  const choosePackage = (plan) => {
    if (isEnterprisePlan(plan)) {
      setCallbackPlan(plan)
      return
    }

    if (getPackageAmount(plan) > 0) {
      setPaymentPlan(plan)
      return
    }

    activatePackage(plan)
  }

  const buyCoins = async () => {
    if (!recruiter?.email) {
      notify('Please login as recruiter to buy coins.', 'error')
      return
    }

    if (!activePackage) {
      notify('Please activate a recruiter package before buying coins.', 'error')
      return
    }

    setCoinBuying(true)
    await startRazorpayPayment({
      amount: coinQuantity * 10,
      description: `${coinQuantity} recruiter wallet coins`,
      name: `${coinQuantity} coins`,
      orderPayload: {
        recruiterEmail: recruiter.email,
        recruiterName: recruiter.name,
        purpose: 'coins',
        coins: coinQuantity,
      },
      onSuccess: async (payload) => {
        setActivePackage(payload.data?.subscription || null)
        window.dispatchEvent(new Event('recruiter-wallet-updated'))
      },
    })
    setCoinBuying(false)
  }

  return (
    <DashboardShell title="Recruiter Pricing" subtitle="Choose a hiring plan for posting jobs, reviewing candidates, and scaling your recruitment workflow.">
      <PaymentDetails details={paymentDetails} />
      {(activePackage?.packageId || activePackage?.packageSnapshot?.name) && (
        <div className="mb-5 rounded-[7px] border border-teal-200 bg-teal-50 p-5">
          <p className="text-xs font-black uppercase tracking-wide text-teal-700">Current Active Package</p>
          <p className="mt-2 text-2xl font-black text-slate-950">{activePackage.packageSnapshot?.name}</p>
          <p className="mt-1 text-sm font-bold text-teal-800">{activePackage.packageSnapshot?.price} / {activePackage.coinBalance || 0} coins left / {activePackage.packageSnapshot?.coinPerJob || 10} coins per job / Active since {new Date(activePackage.activatedAt).toLocaleDateString()}</p>
        </div>
      )}
      <div className="grid gap-5 lg:grid-cols-3">
        {plans.map((plan) => {
          const isActive = isCurrentPackage(plan, activePackage)

          return (
          <article className={`rounded-[7px] border bg-white p-6 shadow-sm ${isActive ? 'border-teal-300 shadow-xl shadow-teal-100' : plan.badge ? 'border-blue-200 shadow-xl shadow-blue-100' : 'border-slate-200'}`} key={plan._id || plan.name}>
            <div className="flex items-center justify-between gap-3">
              <span className={`grid h-12 w-12 place-items-center rounded-[7px] ${isActive ? 'bg-teal-600 text-white' : plan.badge ? 'bg-blue-600 text-white' : 'bg-blue-50 text-blue-600'}`}>
                <CreditCard size={22} />
              </span>
              {isActive ? <span className="rounded-[7px] bg-teal-600 px-3 py-1 text-xs font-black text-white">Active</span> : plan.badge && <span className="rounded-[7px] bg-teal-50 px-3 py-1 text-xs font-black text-teal-700">{plan.badge}</span>}
            </div>
            <h2 className="mt-5 text-2xl font-black text-slate-950">{plan.name}</h2>
            <p className="mt-2 text-sm font-semibold text-slate-500">{plan.description}</p>
            <p className="mt-5 text-3xl font-black text-slate-950">{plan.price}</p>
            <p className="mt-2 text-xs font-black uppercase tracking-wide text-slate-400">{plan.jobLimit || 1} jobs / {getPlanValidityDays(plan)} days / {plan.coinPerJob || 10} coins per job</p>
            <div className="mt-6 grid gap-3">
              {plan.features.map((feature) => (
                <p className="flex items-center gap-3 text-sm font-bold text-slate-600" key={feature}>
                  <CheckCircle2 className="text-teal-500" size={18} />
                  {feature}
                </p>
              ))}
            </div>
            <button
              className={`mt-6 w-full rounded-[7px] px-5 py-3 text-sm font-black transition ${isActive ? 'bg-teal-50 text-teal-700 ring-1 ring-teal-200' : plan.badge ? 'bg-blue-600 text-white shadow-lg shadow-blue-100 hover:bg-blue-700' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
              disabled={isActive}
              onClick={() => choosePackage(plan)}
              type="button"
            >
              {isActive ? 'Current Package' : getPlanButtonLabel(plan)}
            </button>
          </article>
          )
        })}
      </div>
      {callbackPlan && (
        <EnterpriseCallbackModal
          onClose={() => setCallbackPlan(null)}
          onSubmitted={() => {
            setCallbackPlan(null)
            notify('Enterprise callback request sent successfully. Our team will contact you soon.', 'success')
          }}
          plan={callbackPlan}
          recruiter={recruiter}
        />
      )}
      {paymentPlan && (
        <PackagePaymentModal
          activePackage={activePackage}
          onClose={() => setPaymentPlan(null)}
          onPay={async () => {
            const plan = paymentPlan
            setPaymentPlan(null)
            await startRazorpayPayment({
              amount: Math.max(0, getPackageAmount(plan) - (getPackageAmount(plan) * Number(plan.discountPercent || 0)) / 100),
              description: `${plan.name} recruiter package`,
              name: plan.name,
              orderPayload: {
                ...buildPackageRequest(recruiter, plan),
                purpose: 'package',
              },
              onSuccess: async (payload) => {
                setActivePackage(payload.data?.subscription || null)
                window.dispatchEvent(new Event('recruiter-wallet-updated'))
              },
            })
          }}
          processing={paymentProcessing}
          plan={paymentPlan}
        />
      )}

      <div className="mt-6 grid gap-6 lg:grid-cols-2">
        <Panel title="Plan Benefits">
          <div className="grid gap-3">
            {[
              [Sparkles, 'Better hiring visibility across premium job listings'],
              [ShieldCheck, 'Verified recruiter profile and clean hiring workspace'],
            ].map(([Icon, text]) => (
              <p className="flex items-center gap-3 rounded-[7px] bg-blue-50 p-4 text-sm font-bold text-blue-700" key={text}>
                <Icon size={18} />
                {text}
              </p>
            ))}
          </div>
        </Panel>
        <Panel title="Need to buying more coin">
          <div className="rounded-[7px] bg-slate-950 p-5 text-white">
            <p className="text-xs font-black uppercase tracking-wide text-blue-200">Recruiter wallet top-up</p>
            <p className="mt-3 text-3xl font-black">{activePackage?.coinBalance || 0} coins</p>
            <p className="mt-1 text-sm font-semibold text-slate-300">10 coins = INR 100 / one job uses {activePackage?.packageSnapshot?.coinPerJob || 10} coins</p>
          </div>

          <div className="mt-5 grid gap-4">
            <label>
              <span className="text-xs font-black uppercase tracking-wide text-slate-400">Choose coins</span>
              <select
                className="mt-2 w-full rounded-[7px] border border-slate-200 bg-white px-4 py-3 text-sm font-black text-slate-800 outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-100"
                onChange={(event) => setCoinQuantity(Number(event.target.value))}
                value={coinQuantity}
              >
                {[10, 20, 50, 100, 200, 500].map((coins) => (
                  <option key={coins} value={coins}>{coins} coins</option>
                ))}
              </select>
            </label>

            <div className="grid gap-3 rounded-[7px] bg-blue-50 p-4 text-sm font-bold text-blue-800">
              <div className="flex justify-between gap-3"><span>Selected coins</span><span>{coinQuantity}</span></div>
              <div className="flex justify-between gap-3"><span>Payable amount</span><span>INR {coinQuantity * 10}</span></div>
              <div className="flex justify-between gap-3"><span>After payment wallet</span><span>{(activePackage?.coinBalance || 0) + coinQuantity} coins</span></div>
            </div>

            <button
              className="rounded-[7px] bg-blue-600 px-5 py-3 text-sm font-black text-white shadow-lg shadow-blue-100 transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-300"
              disabled={coinBuying || paymentProcessing || !activePackage}
              onClick={buyCoins}
              type="button"
            >
              {coinBuying || paymentProcessing ? 'Processing Payment...' : 'Buy Coins & Pay'}
            </button>
            {!activePackage && <p className="text-xs font-bold text-rose-600">Activate a package before buying coins.</p>}
          </div>
        </Panel>
      </div>
    </DashboardShell>
  )
}

function PackagePaymentModal({ activePackage, onClose, onPay, plan, processing }) {
  const amount = getPackageAmount(plan)
  const discount = Number(plan.discountPercent || 0)
  const payable = Math.max(0, amount - (amount * discount) / 100)
  const coins = getPackageCoins(plan)

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4">
      <div className="w-full max-w-xl rounded-[7px] bg-white p-6 shadow-2xl">
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-sm font-black uppercase tracking-wide text-blue-600">Package Payment</p>
            <h2 className="mt-2 text-3xl font-black text-slate-950">{plan.name}</h2>
            <p className="mt-2 text-sm font-bold text-slate-500">Wallet balance: {activePackage?.coinBalance || 0} coins</p>
          </div>
          <button className="grid h-10 w-10 place-items-center rounded-[7px] bg-slate-100 text-slate-600" onClick={onClose} type="button">x</button>
        </div>

        <div className="mt-6 grid gap-3 rounded-[7px] bg-slate-50 p-4 text-sm font-bold text-slate-700">
          <div className="flex justify-between gap-3"><span>Package amount</span><span>{plan.price}</span></div>
          <div className="flex justify-between gap-3"><span>Discount</span><span>{discount}%</span></div>
          <div className="flex justify-between gap-3 border-t border-slate-200 pt-3 text-slate-950"><span>Payable amount</span><span>INR {payable}</span></div>
          <div className="flex justify-between gap-3 text-teal-700"><span>Coins credited</span><span>{coins} coins</span></div>
        </div>

        <div className="mt-6 flex flex-col justify-end gap-2 sm:flex-row">
          <button className="rounded-[7px] border border-slate-200 bg-transparent px-5 py-2.5 text-sm font-bold text-slate-700 transition hover:bg-slate-50" onClick={onClose} type="button">Cancel</button>
          <button className="rounded-[7px] bg-blue-600 px-5 py-2.5 text-sm font-bold text-white disabled:bg-slate-300" disabled={processing} onClick={onPay} type="button">
            {processing ? 'Opening Razorpay...' : 'Pay with Razorpay'}
          </button>
        </div>
      </div>
    </div>
  )
}

function EnterpriseCallbackModal({ onClose, onSubmitted, plan, recruiter }) {
  const [form, setForm] = useState({
    name: recruiter?.contactPerson || recruiter?.name || '',
    email: recruiter?.email || '',
    phone: recruiter?.phone || '',
    company: recruiter?.companyName || recruiter?.company || recruiter?.name || '',
    candidatesNeeded: '',
    callbackTime: '',
    notes: '',
  })
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!recruiter?.email) return

    Promise.all([
      api.currentAuthUser().catch(() => ({ data: null })),
      api
      .list('employers', `?businessEmail=${encodeURIComponent(recruiter.email)}&limit=1`)
        .catch(() => ({ data: [] })),
    ])
      .then(([userPayload, employerPayload]) => {
        const authUser = userPayload.data
        const payload = employerPayload
        const employer = payload.data?.[0]

        setForm((current) => ({
          ...current,
          name: employer?.contactPerson || recruiter.contactPerson || authUser?.name || recruiter.name || current.name,
          email: authUser?.email || employer?.businessEmail || recruiter.email || current.email,
          phone: authUser?.phone || employer?.phone || recruiter.phone || current.phone,
          company: employer?.companyName || recruiter.companyName || recruiter.company || current.company,
        }))
      })
      .catch(() => null)
  }, [recruiter?.email])

  const update = (key, value) => {
    setForm((current) => ({ ...current, [key]: value }))
  }

  const submit = async (event) => {
    event.preventDefault()
    setError('')

    if (!form.name.trim() || !form.email.trim() || !form.phone.trim() || !form.company.trim()) {
      const message = 'Name, email, phone, and company must be available from recruiter profile.'
      setError(message)
      showToast(message, 'error')
      return
    }

    if (!form.candidatesNeeded || Number(form.candidatesNeeded) <= 0 || !form.callbackTime) {
      const message = 'Please enter candidates needed and choose preferred callback date and time.'
      setError(message)
      showToast(message, 'error')
      return
    }

    setSubmitting(true)
    try {
      await api.create('support-messages', {
        name: form.name.trim(),
        email: form.email.trim().toLowerCase(),
        phone: form.phone.trim(),
        company: form.company.trim(),
        role: 'recruiter',
        subject: 'Enterprise Callback Request',
        packageName: plan.name || 'Enterprise',
        candidatesNeeded: form.candidatesNeeded,
        callbackTime: form.callbackTime,
        source: 'recruiter-enterprise-callback',
        status: 'Open',
        message: [
          `Package: ${plan.name || 'Enterprise'}`,
          `Company: ${form.company.trim()}`,
          form.candidatesNeeded ? `Candidates needed: ${form.candidatesNeeded}` : '',
          form.callbackTime ? `Preferred callback date/time: ${new Date(form.callbackTime).toLocaleString()}` : '',
          form.notes ? `Notes: ${form.notes.trim()}` : '',
        ].filter(Boolean).join('\n'),
      })
      onSubmitted()
    } catch (submitError) {
      const message = submitError.message || 'Callback request failed.'
      setError(message)
      showToast(message, 'error')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/45 p-4">
      <form className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-[7px] bg-white p-6 shadow-2xl" onSubmit={submit}>
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="text-sm font-black uppercase tracking-wide text-blue-600">Enterprise callback</p>
            <h2 className="mt-2 text-3xl font-black text-slate-950">Request a callback</h2>
            <p className="mt-2 text-sm font-bold text-slate-500">Share your details and the admin team will follow up for the Enterprise package.</p>
          </div>
          <button className="grid h-10 w-10 place-items-center rounded-[7px] bg-slate-100 text-slate-600" onClick={onClose} type="button">x</button>
        </div>

        <div className="mt-6 grid gap-4 md:grid-cols-2">
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">Name</span>
            <input className="input mt-2 bg-slate-50 text-slate-500" placeholder="Auto fetched" readOnly value={form.name} />
          </label>
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">Email</span>
            <input className="input mt-2 bg-slate-50 text-slate-500" placeholder="Auto fetched" readOnly type="email" value={form.email} />
          </label>
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">Phone</span>
            <input className="input mt-2 bg-slate-50 text-slate-500" placeholder="Auto fetched" readOnly value={form.phone} />
          </label>
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">Company</span>
            <input className="input mt-2 bg-slate-50 text-slate-500" placeholder="Auto fetched" readOnly value={form.company} />
          </label>
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">How many candidates do you need?</span>
            <input className="input mt-2" min="1" onChange={(event) => update('candidatesNeeded', event.target.value)} placeholder="Enter number of candidates" type="number" value={form.candidatesNeeded} />
          </label>
          <label>
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">Preferred callback time</span>
            <input className="input mt-2" onChange={(event) => update('callbackTime', event.target.value)} type="datetime-local" value={form.callbackTime} />
          </label>
          <label className="md:col-span-2">
            <span className="text-xs font-black uppercase tracking-wide text-slate-400">Notes</span>
            <textarea className="input mt-2 min-h-28" onChange={(event) => update('notes', event.target.value)} placeholder="Hiring requirement, locations, number of jobs..." value={form.notes} />
          </label>
        </div>

        <div className="mt-6 flex flex-col justify-end gap-2 sm:flex-row">
          <button className="rounded-[7px] bg-slate-100 px-5 py-2.5 text-sm font-bold text-slate-700" onClick={onClose} type="button">Cancel</button>
          <button className="rounded-[7px] bg-blue-600 px-5 py-2.5 text-sm font-bold text-white disabled:bg-slate-300" disabled={submitting} type="submit">
            {submitting ? 'Sending...' : 'Send Callback Request'}
          </button>
        </div>
      </form>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Camera, Mail, MapPin, Phone } from 'lucide-react'
import { getStoredUser } from '../routes/authRouting'
import { api } from '../services/api'
import { DashboardShell, Panel } from './CandidateDashboard'
import { showMessageToast, showToast } from '../utils/toast'

export function RecruiterProfilePage() {
  const user = getStoredUser()
  const [editing, setEditing] = useState(false)
  const [saving, setSaving] = useState(false)
  const [logoUploading, setLogoUploading] = useState(false)
  const [message, setMessage] = useState('')
  const [employerId, setEmployerId] = useState('')
  const [profile, setProfile] = useState(() => ({
    name: user?.name || 'Recruiter',
    contactPerson: user?.name || '',
    email: user?.email || 'recruiter@inseet.test',
    phone: '',
    location: 'India',
    industry: 'Recruitment',
    companySize: '',
    website: '',
    logo: '',
  }))
  const initials = profile.name
    .split(' ')
    .map((part) => part[0])
    .join('')
    .slice(0, 2)
    .toUpperCase()

  const update = (key, value) => {
    setProfile((current) => ({ ...current, [key]: value }))
    setMessage('')
  }

  const notify = (text, type) => {
    setMessage('')
    if (text) showMessageToast(text, type ? { type } : {})
  }

  useEffect(() => {
    if (!user?.email) return

    api
      .list('employers', `?businessEmail=${encodeURIComponent(user.email)}&limit=1`)
      .then((payload) => {
        const employer = payload.data?.[0]
        if (!employer) return

        setEmployerId(employer._id || '')
        setProfile({
          name: employer.companyName || user.name || 'Recruiter',
          contactPerson: employer.contactPerson || user.name || '',
          email: employer.businessEmail || user.email,
          phone: employer.phone || user.phone || '',
          location: employer.location || 'India',
          industry: employer.industry || 'Recruitment',
          companySize: employer.companySize || '',
          website: employer.website || '',
          logo: employer.logo || employer.logoUrl || '',
        })
      })
      .catch(() => null)
  }, [user?.email])

  const save = async () => {
    if (!profile.name.trim() || !profile.email.trim()) {
      notify('Company name and business email are required.', 'error')
      return
    }

    setSaving(true)
    try {
      const body = {
        companyName: profile.name,
        contactPerson: profile.contactPerson,
        businessEmail: profile.email,
        phone: profile.phone,
        industry: profile.industry,
        companySize: profile.companySize,
        website: profile.website,
        location: profile.location,
        logo: profile.logo,
        logoUrl: profile.logo,
        status: 'Approved',
        verified: true,
      }
      const payload = employerId
        ? await api.update('employers', employerId, body)
        : await api.create('employers', body)
      const employer = payload.data
      setEmployerId(employer._id || employerId)
      setProfile({
        name: employer.companyName || profile.name,
        contactPerson: employer.contactPerson || profile.contactPerson,
        email: employer.businessEmail || profile.email,
        phone: employer.phone || profile.phone,
        location: employer.location || profile.location,
        industry: employer.industry || profile.industry,
        companySize: employer.companySize || profile.companySize,
        website: employer.website || profile.website,
        logo: employer.logo || employer.logoUrl || profile.logo,
      })

      const currentUser = getStoredUser()
      if (currentUser) {
        localStorage.setItem('authUser', JSON.stringify({
          ...currentUser,
          email: employer.businessEmail || profile.email,
          phone: employer.phone || profile.phone,
          companyName: employer.companyName || profile.name,
          contactPerson: employer.contactPerson || profile.contactPerson,
        }))
      }

      setEditing(false)
      notify('Recruiter profile saved successfully.', 'success')
    } catch (error) {
      notify(error.message || 'Recruiter profile save failed.', 'error')
    } finally {
      setSaving(false)
    }
  }

  const updateLogo = async (event) => {
    const file = event.target.files?.[0]
    if (!file) return

    if (!String(file.type || '').startsWith('image/')) {
      notify('Only image upload is allowed for recruiter profile.', 'error')
      return
    }

    const data = new FormData()
    data.append('image', file)
    data.append('field', 'recruiter-logo')
    data.append('recruiterEmail', user?.email || profile.email || '')
    if (profile.logo) data.append('previousFileUrl', profile.logo)

    setLogoUploading(true)
    setMessage('')

    try {
      const payload = await api.uploadRecruiterProfileImageToSupaCloud(data)
      const url = payload.data?.url
      if (!url) {
        notify('Image uploaded, but public URL was not returned. Check Supa Cloud public bucket setting.', 'error')
        return
      }
      update('logo', url)
      showToast('Profile image uploaded. Click Save to update recruiter profile.', 'success')
    } catch (error) {
      notify(error.message || 'Recruiter profile image upload failed.', 'error')
    } finally {
      setLogoUploading(false)
      event.target.value = ''
    }
  }

  return (
    <DashboardShell title="Recruiter Profile" subtitle="Manage your recruiter identity, company details, contact information, and hiring workspace profile.">
      <div className="grid gap-6 lg:grid-cols-[360px_1fr]">
        <Panel title="Profile Summary">
          <div className="mb-5 flex justify-end">
            {editing ? (
              <div className="flex gap-2">
                <button className="rounded-[7px] bg-slate-100 px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-200" onClick={() => setEditing(false)} type="button">Cancel</button>
                <button className="rounded-[7px] bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-300" disabled={saving} onClick={save} type="button">{saving ? 'Saving...' : 'Save'}</button>
              </div>
            ) : (
              <button className="rounded-[7px] bg-blue-600 px-4 py-2 text-sm font-bold text-white hover:bg-blue-700" onClick={() => setEditing(true)} type="button">Edit Profile</button>
            )}
          </div>
          <div className="flex items-center gap-4">
            <div className="relative">
              <span className="grid h-24 w-24 place-items-center overflow-hidden rounded-[7px] bg-blue-600 text-2xl font-black text-white shadow-lg shadow-blue-100">
                {profile.logo ? <img alt={`${profile.name} logo`} className="h-full w-full object-cover" src={profile.logo} /> : initials}
              </span>
              {editing && (
                <label className="absolute -bottom-2 -right-2 grid h-10 w-10 cursor-pointer place-items-center rounded-[7px] bg-slate-950 text-white shadow-lg transition hover:bg-blue-600">
                  <Camera size={17} />
                  <input accept="image/*" className="hidden" disabled={logoUploading} onChange={updateLogo} type="file" />
                </label>
              )}
            </div>
            <div>
              <h2 className="text-2xl font-black text-slate-950">{profile.name}</h2>
              <p className="mt-1 text-sm font-semibold text-blue-700">Recruiter</p>
              <p className="mt-1 text-sm font-bold text-slate-500">{profile.contactPerson || 'Contact person not added'}</p>
              {editing && <p className="mt-2 text-xs font-bold text-slate-400">{logoUploading ? 'Uploading logo...' : 'Click camera icon to upload company logo'}</p>}
            </div>
          </div>
          <div className="mt-6 grid gap-3 text-sm font-semibold text-slate-600">
            <p className="flex items-center gap-3 rounded-[7px] bg-slate-50 p-4">
              <Mail className="text-blue-600" size={18} />
              {profile.email}
            </p>
            <p className="flex items-center gap-3 rounded-[7px] bg-slate-50 p-4">
              <Phone className="text-blue-600" size={18} />
              {profile.phone || 'Not added'}
            </p>
            <p className="flex items-center gap-3 rounded-[7px] bg-slate-50 p-4">
              <MapPin className="text-blue-600" size={18} />
              {profile.location}
            </p>
          </div>
        </Panel>

        <div className="grid gap-6">
          <Panel title="Company Information">
            {editing ? (
              <div className="grid gap-4 md:grid-cols-2">
                <ProfileField label="Company name" onChange={(value) => update('name', value)} value={profile.name} />
                <ProfileField label="Contact person name" onChange={(value) => update('contactPerson', value)} value={profile.contactPerson} />
                <ProfileField label="Business email" onChange={(value) => update('email', value)} type="email" value={profile.email} />
                <ProfileField label="Phone" onChange={(value) => update('phone', value)} value={profile.phone} />
                <ProfileField label="Industry" onChange={(value) => update('industry', value)} value={profile.industry} />
                <ProfileField label="Company size" onChange={(value) => update('companySize', value)} value={profile.companySize} />
                <ProfileField label="Website" onChange={(value) => update('website', value)} value={profile.website} />
                <ProfileField className="md:col-span-2" label="Office location" onChange={(value) => update('location', value)} value={profile.location} />
              </div>
            ) : (
              <div className="grid gap-4 md:grid-cols-2">
                <InfoItem label="Company name" value={profile.name} />
                <InfoItem label="Contact person" value={profile.contactPerson || 'Not added'} />
                <InfoItem label="Industry" value={profile.industry} />
                <InfoItem label="Company size" value={profile.companySize || 'Not added'} />
                <InfoItem label="Website" value={profile.website || 'Not added'} />
                <InfoItem label="Office location" value={profile.location} />
                <InfoItem label="Verification" value="Verified recruiter profile" />
              </div>
            )}
          </Panel>

        </div>
      </div>
    </DashboardShell>
  )
}

function ProfileField({ className = '', label, onChange, type = 'text', value }) {
  return (
    <label className={className}>
      <span className="text-xs font-black uppercase tracking-wide text-slate-400">{label}</span>
      <input className="mt-2 w-full rounded-[7px] border border-slate-200 bg-white px-4 py-3 text-sm font-semibold outline-none focus:border-blue-500" onChange={(event) => onChange(event.target.value)} type={type} value={value} />
    </label>
  )
}

function InfoItem({ label, value }) {
  return (
    <div className="rounded-[7px] bg-slate-50 p-4">
      <p className="text-xs font-black uppercase tracking-wide text-slate-400">{label}</p>
      <p className="mt-2 text-sm font-bold text-slate-800">{value}</p>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { BarChart3, CalendarDays, CheckCircle2, ClipboardList, Clock3, Eye, Mail, MessageSquare, ShieldCheck, UserPlus, UsersRound } from 'lucide-react'
import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { Button } from '../components/Button'
import { getStoredUser } from '../routes/authRouting'
import { api } from '../services/api'
import { DashboardShell, MetricCard, Panel } from './CandidateDashboard'

function useRecruiterApplications() {
  const user = useMemo(() => getStoredUser(), [])
  const [applications, setApplications] = useState([])

  useEffect(() => {
    if (!user?.email) {
      setApplications([])
      return
    }

    api
      .list('applications', `?recruiterEmail=${encodeURIComponent(user.email)}&sort=-createdAt&limit=100`)
      .then((payload) => setApplications(payload.data || []))
      .catch(() => setApplications([]))
  }, [user?.email])

  return applications
}

function countByStatus(applications, statuses) {
  return applications.filter((item) => statuses.includes(item.status)).length
}

const activeApplicationStatuses = ['New', 'Reviewed', 'Interview']
const recruiterActionStatuses = ['Reviewed', 'Shortlisted', 'Interview', 'Selected', 'Rejected']

function formatDate(value) {
  if (!value) return '-'
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? '-' : date.toLocaleDateString()
}

function getCandidatePhone(application) {
  return String(application?.candidatePhone || application?.phone || '').replace(/\D/g, '')
}

function PhoneReveal({ application }) {
  const [visible, setVisible] = useState(false)
  const phone = getCandidatePhone(application)

  if (!phone) return <span className="text-xs font-semibold text-slate-400">Mobile: -</span>

  return (
    <span className="inline-flex items-center gap-2 text-xs font-semibold text-slate-500">
      <span>Mobile: {visible ? phone : `******${phone.slice(-4)}`}</span>
      <button
        aria-label="View mobile number"
        className="grid h-7 w-7 place-items-center rounded-[7px] bg-blue-50 text-blue-600 transition hover:bg-blue-100"
        onClick={(event) => {
          event.stopPropagation()
          setVisible((value) => !value)
        }}
        type="button"
      >
        <Eye size={14} />
      </button>
    </span>
  )
}

function getStageTone(stage) {
  const tones = {
    New: 'bg-slate-50 text-slate-700 ring-slate-200',
    Reviewed: 'bg-sky-50 text-sky-700 ring-sky-100',
    Shortlisted: 'bg-teal-50 text-teal-700 ring-teal-100',
    Interview: 'bg-violet-50 text-violet-700 ring-violet-100',
    Selected: 'bg-emerald-50 text-emerald-700 ring-emerald-100',
    Rejected: 'bg-rose-50 text-rose-700 ring-rose-100',
  }

  return tones[stage] || 'bg-slate-50 text-slate-700 ring-slate-200'
}

function getStageBar(stage) {
  const tones = {
    New: 'bg-slate-500',
    Reviewed: 'bg-sky-500',
    Shortlisted: 'bg-teal-500',
    Interview: 'bg-violet-500',
    Selected: 'bg-emerald-500',
    Rejected: 'bg-rose-500',
  }

  return tones[stage] || 'bg-slate-500'
}

function getApplicationStatusTone(status) {
  const tones = {
    New: 'bg-slate-50 text-slate-700 ring-slate-200',
    Reviewed: 'bg-sky-50 text-sky-700 ring-sky-100',
    Shortlisted: 'bg-teal-50 text-teal-700 ring-teal-100',
    Interview: 'bg-violet-50 text-violet-700 ring-violet-100',
    Selected: 'bg-emerald-50 text-emerald-700 ring-emerald-100',
    Rejected: 'bg-rose-50 text-rose-700 ring-rose-100',
  }

  return tones[status] || tones.New
}

function ApplicationStatusBadge({ status }) {
  return (
    <span className={`inline-flex rounded-[7px] px-3 py-1 text-xs font-black ring-1 ${getApplicationStatusTone(status)}`}>
      {status || 'New'}
    </span>
  )
}

function CompactMetric({ icon: Icon, label, value, tone = 'blue' }) {
  const tones = {
    blue: 'bg-blue-50 text-blue-700 ring-blue-100',
    slate: 'bg-slate-50 text-slate-700 ring-slate-200',
    teal: 'bg-teal-50 text-teal-700 ring-teal-100',
    violet: 'bg-violet-50 text-violet-700 ring-violet-100',
    emerald: 'bg-emerald-50 text-emerald-700 ring-emerald-100',
    rose: 'bg-rose-50 text-rose-700 ring-rose-100',
  }

  return (
    <div className="rounded-[7px] border border-slate-200 bg-white p-4 shadow-sm">
      <div className={`grid h-10 w-10 place-items-center rounded-[7px] ring-1 ${tones[tone] || tones.blue}`}>
        <Icon size={18} />
      </div>
      <p className="mt-4 text-2xl font-black text-slate-950">{value}</p>
      <p className="mt-1 text-xs font-black uppercase tracking-wide text-slate-400">{label}</p>
    </div>
  )
}

function RecruiterStageSummary({ applications }) {
  const total = applications.length
  const stages = [
    { label: 'New', query: 'new', helper: 'Fresh candidate applications' },
    { label: 'Reviewed', query: 'reviewed', helper: 'Profiles already screened' },
    { label: 'Shortlisted', query: 'shortlisted', helper: 'Ready for next round' },
    { label: 'Interview', query: 'interview', helper: 'Interview pipeline' },
    { label: 'Selected', query: 'selected', helper: 'Final selected candidates' },
    { label: 'Rejected', query: 'rejected', helper: 'Closed with rejection' },
  ].map((stage) => {
    const count = countByStatus(applications, [stage.label])
    const percent = total ? Math.round((count / total) * 100) : 0
    return { ...stage, count, percent }
  })

  const activeCount = countByStatus(applications, activeApplicationStatuses)
  const conversion = total ? Math.round((countByStatus(applications, ['Shortlisted', 'Interview', 'Selected']) / total) * 100) : 0

  return (
    <Panel title="Stage Summary">
      <div className="rounded-[7px] bg-slate-950 p-5 text-white">
        <p className="text-xs font-black uppercase tracking-wide text-blue-200">Recruiter pipeline health</p>
        <div className="mt-4 grid grid-cols-3 gap-3">
          <div>
            <p className="text-2xl font-black">{total}</p>
            <p className="text-xs font-semibold text-slate-300">Total</p>
          </div>
          <div>
            <p className="text-2xl font-black">{activeCount}</p>
            <p className="text-xs font-semibold text-slate-300">Active</p>
          </div>
          <div>
            <p className="text-2xl font-black">{conversion}%</p>
            <p className="text-xs font-semibold text-slate-300">Qualified</p>
          </div>
        </div>
      </div>

      <div className="mt-4 grid gap-3">
        {stages.map((stage) => (
          <Link
            className={`block rounded-[7px] p-4 ring-1 transition hover:-translate-y-0.5 hover:shadow-lg ${getStageTone(stage.label)}`}
            key={stage.label}
            to={`/recruiter-applications?status=${stage.query}`}
          >
            <div className="flex items-start justify-between gap-3">
              <div>
                <p className="font-black">{stage.label}</p>
                <p className="mt-1 text-xs font-semibold opacity-75">{stage.helper}</p>
              </div>
              <div className="text-right">
                <p className="text-2xl font-black">{stage.count}</p>
                <p className="text-xs font-black">{stage.percent}%</p>
              </div>
            </div>
            <div className="mt-4 h-2 overflow-hidden rounded-[7px] bg-white/70">
              <div className={`h-full rounded-[7px] ${getStageBar(stage.label)}`} style={{ width: `${stage.percent}%` }} />
            </div>
          </Link>
        ))}
      </div>
    </Panel>
  )
}

export function RecruiterApplicationsPage() {
  const [searchParams] = useSearchParams()
  const navigate = useNavigate()
  const applications = useRecruiterApplications()
  const [localApplications, setLocalApplications] = useState([])

  useEffect(() => {
    setLocalApplications(applications)
  }, [applications])

  const statusFilter = searchParams.get('status') || 'all'
  const visibleApplications = useMemo(() => {
    if (statusFilter === 'active') {
      return localApplications.filter((item) => activeApplicationStatuses.includes(item.status))
    }
    if (statusFilter === 'reviewed') {
      return localApplications.filter((item) => ['Reviewed', 'Shortlisted', 'Interview', 'Selected', 'Rejected'].includes(item.status))
    }
    if (statusFilter === 'shortlisted') {
      return localApplications.filter((item) => item.status === 'Shortlisted')
    }
    if (statusFilter === 'interview') {
      return localApplications.filter((item) => item.status === 'Interview')
    }
    if (statusFilter === 'new') {
      return localApplications.filter((item) => item.status === 'New')
    }
    if (statusFilter === 'selected') {
      return localApplications.filter((item) => item.status === 'Selected')
    }
    if (statusFilter === 'rejected') {
      return localApplications.filter((item) => item.status === 'Rejected')
    }
    return localApplications
  }, [localApplications, statusFilter])
  const total = localApplications.length
  const active = countByStatus(localApplications, activeApplicationStatuses)
  const pending = countByStatus(localApplications, ['New'])
  const reviewed = countByStatus(localApplications, ['Reviewed', 'Shortlisted', 'Interview', 'Selected', 'Rejected'])
  const shortlisted = countByStatus(localApplications, ['Shortlisted'])
  const interviews = countByStatus(localApplications, ['Interview'])
  const selected = countByStatus(localApplications, ['Selected'])
  const rejected = countByStatus(localApplications, ['Rejected'])
  const pageTitle = statusFilter === 'active' ? 'Active Applications' : 'Applications'
  const pageSubtitle = statusFilter === 'active'
    ? 'Active candidate applications that are in review, interview, or new stages.'
    : 'Track candidate movement across review, shortlist, interview, and offer stages.'

  const updateApplicationStatus = async (application, status) => {
    if (!application?._id || !status || status === application.status) return

    setLocalApplications((items) => items.map((item) => item._id === application._id ? { ...item, status } : item))
    try {
      const payload = await api.update('applications', application._id, { status })
      setLocalApplications((items) => items.map((item) => item._id === application._id ? payload.data : item))
      window.dispatchEvent(new CustomEvent('portalToast', { detail: { message: `Application moved to ${status}` } }))
    } catch (error) {
      setLocalApplications((items) => items.map((item) => item._id === application._id ? application : item))
      window.dispatchEvent(new CustomEvent('portalToast', { detail: { message: error.message || 'Status update failed' } }))
    }
  }

  return (
    <DashboardShell title={pageTitle} subtitle={pageSubtitle}>
      <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-4">
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications">
          <MetricCard icon={ClipboardList} label="Total Applications" value={String(total)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=active">
          <MetricCard icon={UsersRound} label="Active Applications" value={String(active)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=new">
          <MetricCard icon={Clock3} label="New / Pending" value={String(pending)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=reviewed">
          <MetricCard icon={CheckCircle2} label="Reviewed" value={String(reviewed)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=shortlisted">
          <MetricCard icon={UsersRound} label="Shortlisted" value={String(shortlisted)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=interview">
          <MetricCard icon={CalendarDays} label="Interviews" value={String(interviews)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=selected">
          <MetricCard icon={ShieldCheck} label="Selected" value={String(selected)} />
        </Link>
        <Link className="block rounded-[7px] transition hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2" to="/recruiter-applications?status=rejected">
          <MetricCard icon={MessageSquare} label="Rejected" value={String(rejected)} />
        </Link>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_340px]">
        <Panel title={statusFilter === 'active' ? 'Active Applications Table' : 'Application Pipeline'}>
          {visibleApplications.length ? (
            <div className="overflow-hidden rounded-[7px] ring-1 ring-slate-200">
              <div className="overflow-x-auto">
                <table className="min-w-[900px] w-full border-collapse text-left text-sm">
                  <thead className="bg-slate-50 text-xs uppercase text-slate-500">
                    <tr>
                      <th className="px-4 py-3 font-black">Sr No</th>
                      <th className="px-4 py-3 font-black">Candidate</th>
                      <th className="px-4 py-3 font-black">Email / Mobile</th>
                      <th className="px-4 py-3 font-black">Job</th>
                      <th className="px-4 py-3 font-black">Status</th>
                      <th className="px-4 py-3 font-black">Applied</th>
                      <th className="px-4 py-3 font-black">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 bg-white">
                    {visibleApplications.map((item, index) => (
                      <tr
                        className="cursor-pointer align-top hover:bg-blue-50/40"
                        key={item._id || `${item.candidateEmail}-${item.jobTitle}-${index}`}
                        onClick={() => item.candidateEmail && navigate(`/recruiter-applications/candidate/${encodeURIComponent(item.candidateEmail)}`)}
                      >
                        <td className="px-4 py-4 font-black text-slate-500">#{index + 1}</td>
                        <td className="px-4 py-4">
                          <p className="font-black text-slate-950">{item.candidateName || 'Candidate'}</p>
                        </td>
                        <td className="px-4 py-4">
                          <p className="font-semibold text-slate-600">{item.candidateEmail || '-'}</p>
                          <PhoneReveal application={item} />
                        </td>
                        <td className="px-4 py-4">
                          <p className="font-bold text-slate-900">{item.jobTitle || '-'}</p>
                          <p className="mt-1 text-xs font-semibold text-slate-500">{item.companyName || item.company || '-'}</p>
                        </td>
                        <td className="px-4 py-4">
                          <span className="rounded-[7px] bg-blue-50 px-3 py-1 text-xs font-black text-blue-700 ring-1 ring-blue-100">{item.status || 'New'}</span>
                        </td>
                        <td className="px-4 py-4 font-semibold text-slate-600">{formatDate(item.createdAt || item.appliedAt)}</td>
                        <td className="px-4 py-4" onClick={(event) => event.stopPropagation()}>
                          <select
                            className="rounded-[7px] border border-slate-200 bg-white px-3 py-2 text-xs font-black text-slate-700 outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
                            onChange={(event) => updateApplicationStatus(item, event.target.value)}
                            value={recruiterActionStatuses.includes(item.status) ? item.status : ''}
                          >
                            <option value="">Actions</option>
                            {recruiterActionStatuses.map((status) => <option key={status} value={status}>{status}</option>)}
                          </select>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ) : (
            <div className="rounded-[7px] bg-slate-50 p-6 text-sm font-bold text-slate-500">
              {statusFilter === 'active' ? 'There are no active applications yet.' : 'No applications have been received for your posted jobs yet.'}
            </div>
          )}
        </Panel>
        <RecruiterStageSummary applications={localApplications} />
      </div>
    </DashboardShell>
  )
}

